/**
 * Regenerates src/embedded-webui.ts from the freshly built webui/dist and
 * prompts/ — the second half of `npm run build:binary`. The generated file
 * uses `with { type: "text" }` imports so `bun build --compile` embeds every
 * asset into the executable.
 *
 *   node scripts/embed-assets.mjs
 */

import * as fs from "node:fs";
import * as path from "node:path";

const root = path.resolve(import.meta.dirname, "..");
const dist = path.join(root, "webui", "dist");
const prompts = path.join(root, "prompts");
const out = path.join(root, "src", "embedded-webui.ts");

const TEXT_EXT = new Set([".html", ".js", ".mjs", ".css", ".txt", ".json", ".svg", ".map", ".md", ".woff2"]);
const readTree = (dir) => {
  const files = [];
  for (const entry of fs.readdirSync(dir, { withFileTypes: true })) {
    if (entry.isDirectory()) {
      for (const f of readTree(path.join(dir, entry.name))) files.push(`${entry.name}/${f}`);
    } else if (TEXT_EXT.has(path.extname(entry.name).toLowerCase())) {
      files.push(entry.name);
    } else {
      console.warn(`[embed] skipping binary asset: ${entry.name} (add base64 support if needed)`);
    }
  }
  return files;
};

const lines = [
  "// @ts-nocheck",
  "// AUTO-GENERATED by scripts/embed-assets.mjs (npm run build:binary) — do not edit.",
  "// Text imports so Bun's --compile embeds the assets into the executable.",
  "",
];
const webuiEntries = [];
const promptEntries = [];

if (!fs.existsSync(path.join(dist, "index.html"))) {
  console.error("[embed] webui/dist/index.html missing — run `npm run webui:build` first");
  process.exit(1);
}
let n = 0;
for (const rel of readTree(dist)) {
  const id = `w${n++}`;
  lines.push(`import ${id} from "../webui/dist/${rel}" with { type: "text" };`);
  webuiEntries.push(`  "${rel}": ${id},`);
}
if (fs.existsSync(prompts)) {
  for (const name of fs.readdirSync(prompts).filter((f) => f.toLowerCase().endsWith(".md")).sort()) {
    const id = `p${n++}`;
    lines.push(`import ${id} from "../prompts/${name}" with { type: "text" };`);
    promptEntries.push(`  "${name}": ${id},`);
  }
}
lines.push(
  "",
  `export const EMBEDDED_WEBUI: Record<string, string> = {`,
  ...webuiEntries,
  "};",
  "",
  `export const EMBEDDED_PROMPTS: Record<string, string> = {`,
  ...promptEntries,
  "};",
  "",
);
fs.writeFileSync(out, lines.join("\n"));
console.log(`[embed] wrote src/embedded-webui.ts: ${webuiEntries.length} webui assets, ${promptEntries.length} prompt guides`);
